842	                      // focus. The focused element is the selected option or
843	                      // the first in the group, if no option is selected.
844	                      // This is a slight difference, for simplicity, from the
845	                      // native element, where the first element is focused on
846	                      // `Tab` and the _last_ element is focused on `Shift+Tab`
847	                      const isFocusable = isSelected || (!hasSelection && isFirst);
848	                      return (
849	                        <Swatch
850	                          key={value}
851	                          href={href}
852	                          disabled={!orderable}
853	                          value={value}
854	                          name={name}
855	                          variant={id === 'color' ? 'circle' : 'square'}
856	                          selected={isSelected}
857	                          isFocusable={isFocusable}
858	                        >
859	                          {content}
860	                        </Swatch>
861	                      );
862	                    },
863	                  );
864	                  return (
865	                    <SwatchGroup
866	                      key={id}
867	                      value={selectedValue?.value}
868	                      displayName={selectedValue?.name || ''}
869	                      label={intl.formatMessage(
870	                        {
871	                          defaultMessage: '{variantType}',
872	                          id: 'product_view.label.variant_type',
873	                        },
874	                        { variantType: name },
875	                      )}
876	                      handleChange={onVariationChange ? (value: string) => onVariationChange(id, value) : undefined}
877	                    >
878	                      {swatches}
879	                    </SwatchGroup>
880	                  );
881	                })
882	              )}
883	
884	              {/* audit-allow: verbatim from base product-view (index.jsx:754); copy-first requires it unchanged */}
885	              {!isProductASet && !isProductPartOfBundle && (
886	                <VStack align="stretch" maxWidth={'200px'}>
887	                  <Box fontWeight="bold">
888	                    <label htmlFor="quantity">
889	                      {intl.formatMessage({
890	                        defaultMessage: 'Quantity',
891	                        id: 'product_view.label.quantity',
892	                      })}:
893	                    </label>
894	                  </Box>
895	
896	                  <QuantityPicker
897	                    id="quantity"
898	                    step={stepQuantity}
899	                    value={quantity}
900	                    min={minOrderQuantity}
901	                    {...(maxOrderQuantity != null && { max: maxOrderQuantity })}
902	                    onChange={(stringValue: string, numberValue: number) => {
903	                      // Set the Quantity of product to value of input if value number
904	                      if (numberValue >= 0) {
905	                        setQuantity(numberValue);
906	                        if (isProductABundle) setSelectedBundleQuantity(numberValue);
907	                      } else if (stringValue === '') {
908	                        // We want to allow the use to clear the input to start a new input so here we set the quantity to '' so NAN is not displayed
909	                        // User will not be able to add '' qauntity to the cart due to the add to cart button enablement rules
910	                        setQuantity(stringValue);
911	                      }
912	                    }}
913	                    onBlur={(e: React.FocusEvent<HTMLInputElement>) => {
914	                      // Default to 1the `minOrderQuantity` if a user leaves the box with an invalid value
915	                      const value = e.target.value;
916	                      if (parseInt(value) < 0 || value === '') {
917	                        setQuantity(minOrderQuantity);
918	                        if (isProductABundle) setSelectedBundleQuantity(minOrderQuantity);
919	                      }
920	                    }}
921	                    onFocus={(e: React.FocusEvent<HTMLInputElement>) => {
922	                      // This is useful for mobile devices, this allows the user to pop open the keyboard and set the
923	                      // new quantity with one click. NOTE: This is something that can be refactored into the parent
924	                      // component, potentially as a prop called `selectInputOnFocus`.
925	                      e.target.select();
926	                    }}
927	                    productName={product?.name}
928	                  />
929	                </VStack>
930	              )}
931	              <Box ref={errorContainerRef}>
932	                {!showLoading && showOptionsMessage && (
933	                  <Fade in={true}>
934	                    <Text color="orange.600" fontWeight={600} marginBottom={8}>
935	                      {intl.formatMessage({
936	                        defaultMessage: 'Please select all your options above',
937	                      })}
938	                    </Text>
939	                  </Fade>
940	                )}
941	              </Box>
942	              <HideOnDesktop>
943	                {showFullLink && product && (
944	                  <Link to={`/product/${product.master.masterId}`} color="blue.600">
945	                    <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
946	                  </Link>
947	                )}
948	              </HideOnDesktop>
949	              {isProductASet && <p>{product?.shortDescription}</p>}
950	            </VStack>
951	
952	            <Box>
953	              {!showLoading && showInventoryMessage && !customInventoryMessage && (
954	                <Fade in={true}>
955	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
956	                    {inventoryMessage}
957	                  </Text>
958	                </Fade>
959	              )}
960	              {!showLoading && customInventoryMessage && (
961	                <Fade in={true}>
962	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
963	                    {customInventoryMessage}
964	                  </Text>
965	                </Fade>
966	              )}
967	              <Box>
968	                {showDeliveryOptions && (
969	                  <>
970	                    <Box mb={4}>
971	                      <Text fontWeight={600} mb={3}>
972	                        <FormattedMessage defaultMessage="Delivery:" id="product_view.label.delivery" />
973	                      </Text>
974	                      <RadioGroup
975	                        value={pickupInStore ? DELIVERY_OPTIONS.PICKUP : DELIVERY_OPTIONS.DELIVERY}
976	                        onChange={handleDeliveryOptionChange}
977	                        mb={1}
978	                      >
979	                        <Stack direction="column" spacing={2}>
980	                          <Radio value={DELIVERY_OPTIONS.DELIVERY} isDisabled={disableButton}>
981	                            <FormattedMessage
982	                              defaultMessage="Ship to Address"
983	                              id="product_view.label.ship_to_address"
984	                            />
985	                          </Radio>
986	                          {storeLocatorEnabled && (
987	                            <Radio
988	                              value={DELIVERY_OPTIONS.PICKUP}
989	                              isDisabled={!pickupEnabled || (storeName && inventoryId && isSelectedStoreOutOfStock)}
990	                            >
991	                              <FormattedMessage
992	                                defaultMessage="Pick Up in Store"
993	                                id="product_view.label.pickup_in_store"
994	                              />
995	                            </Radio>
996	                          )}
997	                        </Stack>
998	                      </RadioGroup>
999	                    </Box>
1000	
1001	                    {storeLocatorEnabled && (
1002	                      <>
1003	                        {storeName && inventoryId && (
1004	                          <Text color="black" fontWeight={600} mb={2} data-testid="store-stock-status-msg">
1005	                            {!isSelectedStoreOutOfStock
1006	                              ? intl.formatMessage(
1007	                                  {
1008	                                    id: 'product_view.status.in_stock_at_store',
1009	                                    defaultMessage: 'In stock at {storeName}',
1010	                                  },
1011	                                  {
1012	                                    storeName: (
1013	                                      <Link
1014	                                        as="button"
1015	                                        color="blue.600"
1016	                                        textDecoration="underline"
1017	                                        onClick={onOpenStoreLocator}
1018	                                      >
1019	                                        {storeName}
1020	                                      </Link>
1021	                                    ),
1022	                                  },
1023	                                )
1024	                              : intl.formatMessage(
1025	                                  {
1026	                                    id: 'product_view.status.out_of_stock_at_store',
1027	                                    defaultMessage: 'Out of Stock at {storeName}',
1028	                                  },
1029	                                  {
1030	                                    storeName: (
1031	                                      <Link
1032	                                        as="button"
1033	                                        color="blue.600"
1034	                                        textDecoration="underline"
1035	                                        onClick={onOpenStoreLocator}
1036	                                      >
1037	                                        {storeName}
1038	                                      </Link>
1039	                                    ),
1040	                                  },
1041	                                )}
1042	                          </Text>
1043	                        )}
1044	
1045	                        {/* Show label if pickup is disabled due to no store/inventoryId */}
1046	                        {!pickupEnabled && !storeName && !inventoryId && (
1047	                          <Text color="black" fontWeight={600} mb={3} data-testid="pickup-select-store-msg">
1048	                            <FormattedMessage
1049	                              defaultMessage="Pick up in "
1050	                              id="product_view.label.pickup_in_select_store_prefix"
1051	                            />{' '}
1052	                            <Link as="button" color="blue.600" textDecoration="underline" onClick={onOpenStoreLocator}>
1053	                              <FormattedMessage
1054	                                defaultMessage="Select Store"
1055	                                id="product_view.label.select_store_link"
1056	                              />
1057	                            </Link>
1058	                          </Text>
1059	                        )}
1060	                      </>
1061	                    )}
1062	                  </>
1063	                )}
1064	                <Box display={isProductPartOfSet ? 'block' : ['none', 'none', 'none', 'block']}>
1065	                  {renderActionButtons()}
1066	                </Box>
1067	              </Box>
1068	            </Box>
1069	          </VStack>
1070	        </Flex>
1071	
1072	        {/* Sticky call-to-action buttons for mobile and certain product types */}
1073	        <Box
1074	          position="fixed"
1075	          bg="white"
1076	          width="100%"
1077	          display={isProductPartOfSet || isProductPartOfBundle ? 'none' : ['block', 'block', 'block', 'none']}
1078	          p={[4, 4, 6]}
1079	          left={0}
1080	          bottom={0}
1081	          zIndex={2}
1082	          boxShadow={theme.shadows.top}
1083	        >
1084	          {renderActionButtons()}
1085	        </Box>
1086	
1087	        {/* Loading overlay during express payment confirmation */}
1088	        {confirmingBasket && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
1089	      </Flex>
1090	    );
1091	  },
1092	);
1093	
1094	ProductView.displayName = 'ProductView';
1095	
1096	/*
1097	 * The base file's `ProductViewHeader.propTypes` / `ProductView.propTypes` blocks are not
1098	 * carried over: the `ProductViewHeaderProps` / `ProductViewProps` types above express the
1099	 * same prop contract, and do so at compile time for every caller rather than as a dev-only
1100	 * runtime warning. Keeping both would duplicate the contract in two places that can drift.
1101	 */
1102	
1103	export default ProductView;
1104

