77	import Island from '@salesforce/retail-react-app/app/components/island';
78	
79	import { HTTPNotFound, HTTPError } from '@salesforce/pwa-kit-react-sdk/ssr/universal/errors';
80	import logger from '@salesforce/retail-react-app/app/utils/logger-instance';
81	
82	// constant
83	import {
84	  API_ERROR_MESSAGE,
85	  EINSTEIN_RECOMMENDERS,
86	  MAX_CACHE_AGE,
87	  TOAST_ACTION_VIEW_WISHLIST,
88	  TOAST_MESSAGE_ADDED_TO_WISHLIST,
89	  TOAST_MESSAGE_ALREADY_IN_WISHLIST,
90	  STALE_WHILE_REVALIDATE,
91	} from '@salesforce/retail-react-app/app/constants';
92	import { rebuildPathWithParams } from '@salesforce/retail-react-app/app/utils/url';
93	import { useHistory, useLocation, useParams } from 'react-router-dom';
94	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
95	import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
96	import { useStoreLocatorModal } from '@salesforce/retail-react-app/app/hooks/use-store-locator';
97	import { isPickupMethod } from '@salesforce/retail-react-app/app/utils/shipment-utils';
98	import { useProductInventory } from '@salesforce/retail-react-app/app/hooks/use-product-inventory';
99	
100	/*
101	 * `@salesforce/retail-react-app` ships no TypeScript types (see
102	 * overrides/app/types/vendor.d.ts, which falls back to an untyped catch-all for its
103	 * subpaths), so the product / variant / category values this page threads between base
104	 * hooks and base components have no compile-time shape *from that package*. But the shapes
105	 * themselves are `commerce-sdk-isomorphic`'s, and it does export them as
106	 * `ShopperProductsTypes.Product` / `.Variant` / `.Category` — so these aliases are a
107	 * deliberate temporary gap, not proof that no type is available, and AGENTS.md's Type
108	 * Definitions rule says to import those directly. Deferred to a follow-up only because the
109	 * substitution also clears three `no-explicit-any` warnings, moving a lint count this branch
110	 * holds as an invariant. See the same note in `components/product-view/index.tsx`.
111	 */
112	type SfccProduct = any;
113	type SfccVariant = any;
114	type SfccCategory = any;
115	
116	/*
117	 * `@salesforce/commerce-sdk-react` types its query/mutation `parameters` more narrowly than
118	 * the base JS page satisfies (it types several always-present values as optional, and takes
119	 * `ids` as an array where the base joins them itself). The casts marked "SDK param widening"
120	 * below exist only to reconcile that; each passes exactly the value the base file passes, so
121	 * none of them changes runtime behaviour.
122	 */
123	
124	/** A basket line item as this page assembles it before handing it to the baskets API. */
125	type BasketLineItem = {
126	  productId?: string;
127	  id?: string;
128	  price?: number;
129	  quantity?: number;
130	  inventoryId?: string;
131	  shipmentId?: string;
132	  bundledProductItems?: Array<{ productId?: string; quantity?: number }>;
133	};
134	
135	/** A child product selection within a product set or bundle. */
136	type ChildProductSelection = {
137	  product?: SfccProduct;
138	  variant?: SfccVariant;
139	  quantity?: number;
140	};
141	
142	/** The imperative handle ProductView exposes for set/bundle child validation. */
143	type ChildProductRef = {
144	  ref: HTMLDivElement | null;
145	  validateOrderability: ProductViewRefScope['validateOrderability'];
146	};
147	
148	/** One row of the array the base ProductView passes to `addToCart`. */
149	type ProductSelectionValue = {
150	  product?: SfccProduct;
151	  variant?: SfccVariant;
152	  quantity?: number;
153	};
154	
155	/**
156	 * Errors thrown by the commerce SDK carry the originating `Response`, which the base
157	 * page reads to map an API status onto an SSR-visible HTTP error.
158	 */
159	type CommerceApiError = Error & { response?: { status?: number } };
160	
161	const ProductDetail = () => {
162	  // react-intl returns already-bound methods, so destructuring them cannot unbind anything —
163	  // the rule cannot see that. `formatNumber` is SFCC-89's addition; the base file destructures
164	  // `formatMessage` alone. It feeds `formatPrice` below.
165	  // eslint-disable-next-line @typescript-eslint/unbound-method
166	  const { formatMessage, formatNumber } = useIntl();
167	  const history = useHistory();
168	  const location = useLocation();
169	  const einstein = useEinstein();
170	  const dataCloud = useDataCloud();
171	  const activeData = useActiveData();
172	  const toast = useToast();
173	  const navigate = useNavigation();
174	  const customerId = useCustomerId();
175	  const { onOpen: onOpenStoreLocator } = useStoreLocatorModal();
176	  const multishipEnabled = getConfig()?.app?.multishipEnabled ?? true;
177	  const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
178	
179	  /****************************** Basket *********************************/
180	  const { data: basket, isLoading: isBasketLoading } = useCurrentBasket();
181	  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();
182	  const updateItemsInBasketMutation = useShopperBasketsMutation('updateItemsInBasket');
183	  const { res } = useServerContext();
184	  if (res) {
185	    res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
186	  }
187	
188	  /*************************** Pick up in Store ********************/
189	  const { selectedStore } = useSelectedStore();
190	  const selectedInventoryId = selectedStore?.inventoryId || null;
191	
192	  const { addInventoryIdsToPickupItems, updateDefaultShipmentIfNeeded, hasPickupItems } = usePickupShipment(basket);
193	
194	  /*************************** Multiship ********************/
195	  const { getShipmentIdForItems } = useMultiship(basket);
196	
197	  /*************************** Product Detail and Category ********************/
198	  const { productId } = useParams<{ productId?: string }>();
199	  const urlParams = new URLSearchParams(location.search);
200	  // SDK param widening — this component only mounts on `/product/:productId`, so one of the
201	  // two is always present. `useParams` types every segment optional by design — see the
202	  // comment on the react-router-dom shim in overrides/app/types/vendor.d.ts.
203	  const requestedProductId = (urlParams.get('pid') || productId) as string;
204	  const {
205	    data: productResponse,
206	    isLoading: isProductLoading,
207	    isError: isProductError,
208	    error: productError,
209	  } = useProduct(
210	    {
211	      parameters: {
212	        id: requestedProductId,
213	        perPricebook: true,
214	        expand: [
215	          'availability',
216	          'promotions',
217	          'options',
218	          'images',
219	          'prices',
220	          'variations',
221	          'set_products',
222	          'bundled_products',
223	          'page_meta_tags',
224	        ],
225	        allImages: true,
226	        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
227	      },
228	    },
229	    {
230	      // When shoppers select a different variant (and the app fetches the new data),
231	      // the old data is still rendered (and not the skeletons).
232	      //
233	      // Load-bearing for accessibility, beyond the loading behaviour it was added for. The price
234	      // carries `aria-live` (zimmProductPrice), and a live region only announces a change if the
235	      // region already existed — a region inserted together with its content is silent. Keeping
236	      // the previous data means `ZimmProductContent` (rendered by the `StaticProductHeader`
237	      // partial) never unmounts on a variant change, so the price element survives and React
238	      // mutates its text in place, which is what gets announced.
239	      // Remove this option and the region is destroyed and rebuilt on every swatch click, and the
240	      // price stops being announced (WCAG 2.2 AA 4.1.3). No gate catches that: the atom's own test
241	      // renders it directly, and axe sees a well-formed region either way.
242	      keepPreviousData: true,
243	    },
244	  );
245	
246	  // Note: Since category needs id from product detail, it can't be server side rendered atm
247	  // until we can do dependent query on server
248	  const {
249	    data: category,
250	    isError: isCategoryError,
251	    error: categoryError,
252	  } = useCategory({
253	    parameters: {
254	      // SDK param widening — `useCategory` is a no-op until the product resolves, exactly as
255	      // in the base file.
256	      id: productResponse?.primaryCategoryId as string,
257	      levels: 1,
258	    },
259	  });
260	
261	  /****************************** Colour Swatches (SFCC-91) ***********************/
262	  const urlColour = new URLSearchParams(location.search).get(SFCC_COLOUR_ATTRIBUTE_ID) ?? undefined;
263	  const [shopperSelectedColour, setShopperSelectedColour] = useState<string | undefined>(urlColour);
264	
265	  // Keep shopperSelectedColour in sync when ?color= changes in the URL externally (browser
266	  // back/forward, or history.replace from another handler) or when the product changes while
267	  // the component stays mounted. Without this, useState only captures the mount-time value.
268	  useEffect(() => {
269	    setShopperSelectedColour(urlColour);
270	    // eslint-disable-next-line react-hooks/exhaustive-deps
271	  }, [urlColour, requestedProductId]);
272	
273	  // history.replace updates ?color= in the URL. useDerivedProduct inside ProductView reads
274	  // URL params via usePDPSearchParams/useVariationParams on every location change, so this
275	  // is the same mechanism as clicking a base swatch <a href="?color=value"> — no
276	  // controlledVariationValues or onVariationChange needed (those are for bundle/child products).
277	  const handleColourSelect = (value: string) => {
278	    setShopperSelectedColour(value);
279	    const params = new URLSearchParams(location.search);
280	    params.set(SFCC_COLOUR_ATTRIBUTE_ID, value);
281	    history.replace(`${location.pathname}?${params.toString()}`);
282	  };
283	
284	  const colourVariants: ColourVariant[] = (() => {
285	    const colourAttr = productResponse?.variationAttributes?.find(
286	      (attr: { id: string }) => attr.id === SFCC_COLOUR_ATTRIBUTE_ID,
287	    );
288	    if (!colourAttr?.values) return [];
289	    return colourAttr.values.map((v: { value: string; name?: string; orderable?: boolean }) => {
290	      const groups = filterImageGroups(productResponse?.imageGroups ?? [], {
291	        viewType: 'swatch',
292	        variationValues: { [SFCC_COLOUR_ATTRIBUTE_ID]: v.value },
293	      }) as Array<{ images?: Array<{ link?: string; disBaseLink?: string }> }>;
294	      const firstImage = groups?.[0]?.images?.[0];
295	      const imageUrl = firstImage?.disBaseLink ?? firstImage?.link;
296	      return { value: v.value, name: v.name ?? v.value, imageUrl, orderable: v.orderable ?? true };
297	    });
298	  })();
299	
300	  const isOffered = (value: string | undefined) =>
301	    value !== undefined && colourVariants.some((v) => v.value === value && Boolean(v.imageUrl) && v.orderable);
302	  const firstOfferedColour = colourVariants.find((v) => v.imageUrl && v.orderable)?.value;
303	  // urlColour is read from location.search on every render so it is always current —
304	  // prioritised first so an external URL change is reflected immediately without waiting
305	  // for the shopperSelectedColour sync effect to fire.
306	  const selectedColour =
307	    [urlColour, shopperSelectedColour, productResponse?.variationValues?.color].find(isOffered) ?? firstOfferedColour;
308	
309	  /****************************** Sets and Bundles *********************************/
310	  const [childProductSelection, setChildProductSelection] = useState<Record<string, ChildProductSelection>>({});
311	  const [childProductOrderability, setChildProductOrderability] = useState<Record<string, ChildProductOrderability>>(
312	    {},
313	  );
314	  const [selectedBundleQuantity, setSelectedBundleQuantity] = useState(1);
315	  const childProductRefs = React.useRef<Record<string, ChildProductRef>>({});
316	  // Deviation from the base file: `?.` on `type`. The base reads `productResponse?.type.set`,
317	  // which throws if the API ever returns a product without `type` (the SDK types it optional).
318	  // The two only differ in that already-broken case.
319	  const isProductASet = productResponse?.type?.set;
320	  const isProductABundle = productResponse?.type?.bundle;
321	
322	  const childVariantIds =
323	    isProductABundle || isProductASet
324	      ? Object.keys(childProductSelection)?.map(
325	          (key) => childProductSelection[key].variant?.productId || childProductSelection[key].product?.id,
326	        )
327	      : [];
328	
329	  const { data: variantProductData } = useProducts(
330	    {
331	      parameters: {
332	        // SDK param widening — the base file joins the ids itself and the SDK forwards the
333	        // value verbatim into the query string.
334	        ids: childVariantIds.join(',') as unknown as string[],
335	        allImages: false,
336	        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
337	        expand: ['availability', 'variations'],
338	        select: '(data.(id,inventory,inventories,master))',
339	      },
340	    },
341	    {
342	      enabled: childVariantIds.length > 0,
343	      keepPreviousData: true,
344	    },
345	  );
346	
347	  const product: SfccProduct = useProductInventory(
348	    productResponse,
349	    variantProductData,
350	    selectedInventoryId,
351	    isProductASet,
352	    isProductABundle,
353	  );
354	
355	  /**************** Error Handling ****************/
356	
357	  if (isProductError) {
358	    const errorStatus = (productError as CommerceApiError | null)?.response?.status;
359	    switch (errorStatus) {
360	      case 404:
361	        throw new HTTPNotFound('Product Not Found.');
362	      default:
363	        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
364	    }
365	  }
366	  if (isCategoryError) {
367	    const errorStatus = (categoryError as CommerceApiError | null)?.response?.status;
368	    switch (errorStatus) {
369	      case 404:
370	        throw new HTTPNotFound('Category Not Found.');
371	      default:
372	        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
373	    }
374	  }
375	
376	  const [primaryCategory, setPrimaryCategory] = useState<SfccCategory>(category);
377	  const variant = useVariant(product);
378	
379	  // SFCC-194 — Was/Now sale price.
380	  //
381	  // Two URL states need correct priceData (mirrors feature/SFCC-194_pdp-was-now-sale-price):
382	  //
383	  //   Colour-only  → ?color=JJ8UTXX           (no pid; product is still the master)
384	  //   Colour+size  → ?color=JJ8UTXX&pid=…M    (pid present; product switches to standalone
385	  //                                              variant which lacks tieredPrices reliably)
386	  //
387	  // Strategy: keep the master product's variants[] as the authoritative tieredPrices source.
388	  // Filter them by pid (exact) or colour (set) from the URL, then call getPriceData on the
389	  // scoped result. This is overridden into renderHeader so the base ProductView's own
390	  // getPriceData call (which reads the standalone variant and loses tieredPrices) is bypassed.
391	  const masterProductRef = useRef<SfccProduct | null>(null);
392	  useEffect(() => {
393	    // Guard matches exactly what the memo reads from the cache: id (for the
394	    // cachedMasterMatchesCurrent check) and variants[] (for the filter). A partial SFCC
395	    // response that satisfies type.master but lacks either field is not useful — skip it
396	    // rather than writing a cache entry that would fall through to the deep-link fallback
397	    // one guard too late.
398	    if (productResponse?.type?.master && productResponse.id && productResponse.variants?.length) {
399	      masterProductRef.current = productResponse;
400	    }
401	  }, [productResponse]);
402	
403	  const urlPid = urlParams.get('pid') ?? undefined;
404	  const variantScopedPriceData = useMemo(
405	    () => selectVariantScopedPriceData(product, masterProductRef.current, urlPid, urlColour),
406	    // Re-runs when the fetched product changes (standalone variant arrives) or the URL
407	    // selection changes — both are signals the displayed price must update.
408	    // masterProductRef is a ref so it is intentionally absent from deps.
