977	               * `ZimmProductMeta`'s recipe owning both 28px hops — the one below the accordions and
978	               * the one between its own two rows. Hence no spacing props on the Box. The molecule
979	               * returns null when it has neither value to show.
980	               */}
981	              <Box>
982	                <InformationAccordion product={product} />
983	                <ZimmProductMeta modelInfo={staticInfo?.modelInfo} styleCode={staticInfo?.styleCode} />
984	              </Box>
985	            </Island>
986	          </Fragment>
987	        )}
988	
989	        {/* Product Recommendations */}
990	        <Stack spacing={16}>
991	          {!isProductASet && (
992	            <Island hydrateOn={'visible'}>
993	              <RecommendedProducts
994	                title={
995	                  <FormattedMessage
996	                    defaultMessage="Complete the Set"
997	                    id="product_detail.recommended_products.title.complete_set"
998	                  />
999	                }
1000	                recommender={EINSTEIN_RECOMMENDERS.PDP_COMPLETE_SET}
1001	                products={[product]}
1002	                mx={{ base: -4, md: -8, lg: 0 }}
1003	                shouldFetch={() => product?.id}
1004	              />
1005	            </Island>
1006	          )}
1007	          <Island hydrateOn={'visible'}>
1008	            <RecommendedProducts
1009	              title={
1010	                <FormattedMessage
1011	                  defaultMessage="You might also like"
1012	                  id="product_detail.recommended_products.title.might_also_like"
1013	                />
1014	              }
1015	              recommender={EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE}
1016	              products={[product]}
1017	              mx={{ base: -4, md: -8, lg: 0 }}
1018	              shouldFetch={() => product?.id}
1019	            />
1020	          </Island>
1021	
1022	          <Island hydrateOn={'visible'}>
1023	            <RecommendedProducts
1024	              // The Recently Viewed recommender doesn't use `products`, so instead we
1025	              // provide a key to update the recommendations on navigation.
1026	              key={location.key}
1027	              title={
1028	                <FormattedMessage
1029	                  defaultMessage="Recently Viewed"
1030	                  id="product_detail.recommended_products.title.recently_viewed"
1031	                />
1032	              }
1033	              recommender={EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED}
1034	              mx={{ base: -4, md: -8, lg: 0 }}
1035	            />
1036	          </Island>
1037	        </Stack>
1038	      </Stack>
1039	    </Box>
1040	  );
1041	};
1042	
1043	ProductDetail.getTemplateName = () => 'product-detail';
1044	
1045	/*
1046	 * The base file declares `ProductDetail.propTypes = {match: PropTypes.object}` purely as
1047	 * documentation — the component takes no props and never reads `match`. The TypeScript
1048	 * signature above expresses the same thing at compile time, so the runtime `prop-types`
1049	 * declaration is not carried over.
1050	 */
1051	
1052	export default ProductDetail;
1053

