const el = document.querySelector('[data-testid="pdp-colour-swatches"]');
if (!el) {
  JSON.stringify({found:false, radiogroups: [...document.querySelectorAll('[role="radiogroup"]')].map(r=>r.getAttribute('aria-label'))});
} else {
  const rect = el.getBoundingClientRect();
  const swatches = [...el.querySelectorAll('[role="radio"]')].map(s => {
    const r = s.getBoundingClientRect();
    return {value: s.dataset.swatchValue, w: r.width, h: r.height, checked: s.getAttribute('aria-checked')};
  });
  JSON.stringify({found:true, containerWidth: rect.width, swatches});
}

const btn = document.querySelector('[data-swatch-value="GRN"]');
btn.click();
await new Promise(r => setTimeout(r, 800));
const img = document.querySelector('main img[alt*="large"]');
JSON.stringify({
  url: window.location.href,
  imgSrcAfter: img ? img.src : null,
  greenChecked: document.querySelector('[data-swatch-value="GRN"]')?.getAttribute('aria-checked'),
  redChecked: document.querySelector('[data-swatch-value="RED"]')?.getAttribute('aria-checked'),
});

const focusable = document.querySelector('[role="radio"][tabindex="0"]');
focusable.focus();
const seq = [];
for (let i = 0; i < 5; i++) {
  const ev = new KeyboardEvent('keydown', {key: 'ArrowRight', bubbles: true});
  document.activeElement.dispatchEvent(ev);
  await new Promise(r => setTimeout(r, 50));
  seq.push({active: document.activeElement.dataset.swatchValue, checked: document.activeElement.getAttribute('aria-checked')});
}
JSON.stringify(seq);
